<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="robots" content="noindex, nofollow">
    <title>TradeX Client Portal</title>
    <style>
        :root{--bg:#06090f;--surface:#101923;--gold:#c9a96b;--gold-hi:#e2c98f;--text:#f5f0e6;--muted:#a5acb4;--border:#554630}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 100% 0,#142231 0,transparent 36%),var(--bg);color:var(--text);font:15px/1.55 Inter,ui-sans-serif,system-ui,sans-serif}.shell{width:min(1120px,calc(100% - 36px));margin:auto}.top{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid rgba(201,169,107,.25)}.brand{color:var(--text);font-size:21px;font-weight:800;letter-spacing:.11em;text-decoration:none}.brand b,.eyebrow,.step{color:var(--gold)}.brand small{display:block;color:var(--gold);font-size:9px;letter-spacing:.2em}.top nav,.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.top a{color:inherit;text-decoration:none}button,.button{appearance:none;border:1px solid var(--border);border-radius:11px;padding:11px 16px;background:#0b1119;color:var(--text);cursor:pointer;font:inherit;font-weight:700}button.primary,.button.primary{background:linear-gradient(135deg,var(--gold-hi),var(--gold));border-color:transparent;color:#171207}button.ghost{background:transparent}.hero{display:grid;grid-template-columns:1.2fr .8fr;align-items:center;gap:32px;padding:74px 0 38px}.eyebrow,.step{font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.hero h1{max-width:760px;margin:12px 0 20px;font:clamp(38px,6vw,70px)/.98 Georgia,serif}.hero h1 em{color:var(--gold);font-style:normal}.hero p,.panel p,.item p{color:var(--muted)}.hero p{max-width:680px;font-size:18px}.hero-card,.panel{padding:26px;border:1px solid rgba(201,169,107,.3);border-radius:20px;background:linear-gradient(145deg,rgba(21,31,43,.96),rgba(10,15,22,.96));box-shadow:0 24px 60px rgba(0,0,0,.3)}.hero-card ol{padding-left:20px;color:var(--muted)}.hero-card li+li{margin-top:10px}.portal{padding:24px 0 70px}.auth-grid,.dashboard{display:grid;grid-template-columns:1fr 1fr;gap:20px}.dashboard{grid-template-columns:220px 1fr}.panel h2{margin:0 0 5px;font:32px/1.1 Georgia,serif}.form-grid{display:grid;gap:12px;margin-top:20px}.two,.data-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:6px}.field label,.field>span{color:var(--muted);font-size:12px;font-weight:700}.field input,.field select{width:100%;padding:12px;border:1px solid #354355;border-radius:10px;background:#080d13;color:var(--text);font:inherit}.notice{margin:16px 0;padding:12px 14px;border:1px solid #294665;border-radius:10px;background:#112033;color:#c6d8ee}.notice.error{border-color:#713338;background:#2a1518;color:#ffd5d7}.notice.success{border-color:#256248;background:#10281f;color:#c9f5d9}.hidden{display:none!important}.qr{width:190px;max-width:100%;padding:10px;border-radius:12px;background:#fff}.side{position:sticky;top:16px;height:max-content}.side button{display:block;width:100%;border:0;border-radius:8px;background:transparent;text-align:left}.side button.active{background:var(--gold);color:#171207}.data-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.metric,.item{padding:17px;border:1px solid rgba(255,255,255,.1);border-radius:14px;background:#0b121b}.metric span{display:block;color:var(--muted);font-size:12px}.metric strong{display:block;margin-top:5px;font-size:18px}.course-list,.method-list,.broker-list{display:grid;gap:12px;margin-top:18px}.item h3,.item p{margin:0 0 6px}.item .actions{margin-top:13px}.video{width:100%;margin-top:16px;border-radius:13px;background:#000}.empty{padding:28px 0;color:var(--muted)}.loading{opacity:.68;pointer-events:none}@media(max-width:760px){.top nav{display:none}.hero,.auth-grid,.dashboard,.two,.data-grid{grid-template-columns:1fr}.hero{padding-top:45px}.side{position:static;display:flex;overflow:auto;gap:7px}.side button{width:auto;white-space:nowrap}.shell{width:min(100% - 24px,1120px)}}
    </style>
</head>
<body>
<header class="shell top"><a class="brand" href="/"><span>TRADE<b>X</b><small>CLIENT PORTAL</small></span></a><nav><a href="/">Public website</a><button id="signout" class="ghost hidden">Sign out</button></nav></header>
<main class="shell">
    <section id="landing" class="hero">
        <div><div class="eyebrow">Secure client access</div><h1>Your TradeX <em>workspace</em>, on your terms.</h1><p>Create an account, verify your identity, purchase eligible access, learn through protected video playback, and manage supported broker onboarding from one account.</p><div class="actions"><button class="primary" data-screen="register">Create account</button><button data-screen="login">Sign in</button></div></div>
        <aside class="hero-card"><strong>Protected account flow</strong><ol><li>Registration uses email and WhatsApp verification.</li><li>Authenticator-based MFA protects every sign-in.</li><li>Payments and learning access are determined by the server.</li><li>Video playback uses short-lived protected sessions.</li></ol></aside>
    </section>
    <section id="auth" class="portal hidden">
        <div id="auth-message"></div>
        <div class="auth-grid">
            <article class="panel" id="login-panel"><div class="eyebrow">Existing client</div><h2>Sign in securely.</h2><p>Your account needs an authenticator or recovery code.</p><form id="login-form" class="form-grid"><label class="field"><span>Email</span><input name="email" type="email" autocomplete="email" required></label><label class="field"><span>Password</span><input name="password" type="password" autocomplete="current-password" required></label><label class="field"><span>Authenticator or recovery code</span><input name="mfa" required placeholder="6-digit authenticator code"></label><label class="field"><span>Method</span><select name="mfa_type"><option value="totp_code">Authenticator code</option><option value="recovery_code">Recovery code</option></select></label><button class="primary" type="submit">Sign in to TradeX</button></form></article>
            <article class="panel" id="register-panel"><div class="eyebrow">New client</div><h2>Create your account.</h2><p>Use a personal email and WhatsApp number. You will verify both before activation.</p><form id="register-form" class="form-grid"><div class="two"><label class="field"><span>Full name</span><input name="name" required minlength="2" autocomplete="name"></label><label class="field"><span>Country code</span><input name="country_code" value="LK" required maxlength="2" autocomplete="country"></label></div><label class="field"><span>Email</span><input name="email" type="email" required autocomplete="email"></label><label class="field"><span>WhatsApp number</span><input name="whatsapp_number" type="tel" required placeholder="+947XXXXXXXX" autocomplete="tel"></label><div class="two"><label class="field"><span>Password</span><input name="password" type="password" required minlength="8" autocomplete="new-password"></label><label class="field"><span>Confirm password</span><input name="password_confirmation" type="password" required minlength="8" autocomplete="new-password"></label></div><label class="field"><span>Referral code (optional)</span><input name="referral_code" maxlength="30"></label><input name="language_code" value="en" type="hidden"><button class="primary" type="submit">Start secure registration</button></form></article>
        </div>
        <div id="registration-flow" class="panel hidden"><div class="step" id="registration-step">Verification</div><h2 id="registration-title">Verify your email.</h2><p id="registration-copy">Enter the code sent to your email address.</p><img id="totp-qr" class="qr hidden" alt="TradeX authenticator setup QR code"><form id="verification-form" class="form-grid"><label class="field"><span id="verification-label">Email code</span><input id="verification-code" inputmode="numeric" autocomplete="one-time-code" required></label><div class="actions"><button class="primary" type="submit" id="verification-submit">Verify email</button><button type="button" id="verification-resend">Resend code</button></div></form></div>
    </section>
    <section id="portal" class="portal hidden"><div class="dashboard"><aside class="panel side"><button data-view="overview" class="active">Overview</button><button data-view="learning">My learning</button><button data-view="purchase">Access &amp; purchase</button><button data-view="brokers">Broker onboarding</button></aside><section class="panel"><div id="portal-message"></div><div id="portal-content"><p class="empty">Loading your secure workspace…</p></div></section></div></section>
</main>
<script src="{{ asset('client-portal.js') }}" defer></script>
</body>
</html>
